/**
 * Differential proof (I7, PLAN 2.3): the TypeScript port must reproduce the Solidity library EXACTLY on every vector
 * generated by contracts/test/vectors/GenVectors.t.sol. Regenerate + run: `pnpm prove:diff`.
 * If the vector files are absent (fresh clone without Foundry), the suite is skipped unless PROVE_DIFF=1.
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { advanceAnchor, compute, type Breakdown, type Config, type Params } from "../src/fee.ts";

const dir = fileURLToPath(new URL("../../data/vectors/", import.meta.url));
const feePath = `${dir}fee-vectors.json`;
const anchorPath = `${dir}anchor-vectors.json`;
const present = existsSync(feePath) && existsSync(anchorPath);
const strict = process.env.PROVE_DIFF === "1";

interface FeeVector {
  inputs: {
    cfg: Config;
    params: Params;
    oracleRaw: string;
    markRaw: string;
    anchorMarkRaw: string;
    sqrtPriceX96: string;
    sqrtPriceTopX96: string;
    zeroForOne: boolean;
    readOk: boolean;
  };
  expected: { fee: number; reason: number; gapBps: string; premiumBps: string; moveBps: string; arb: boolean; withPressure: boolean };
}
interface AnchorVector {
  inputs: { anchorMark: string; anchorTime: string; markRaw: string; now: string; tau: string };
  expected: { mark: string; time: string };
}

const asJson = (b: Breakdown) => ({
  fee: b.fee,
  reason: b.reason,
  gapBps: b.gapBps.toString(),
  premiumBps: b.premiumBps.toString(),
  moveBps: b.moveBps.toString(),
  arb: b.arb,
  withPressure: b.withPressure,
});

describe.skipIf(!present && !strict)("differential: Solidity == TypeScript", () => {
  it("vector files exist", () => {
    expect(present, "run `pnpm prove:diff` to generate backend/data/vectors/*.json").toBe(true);
  });

  it("10,000/10,000 fee vectors match on every Breakdown field", () => {
    const vectors = JSON.parse(readFileSync(feePath, "utf8")) as FeeVector[];
    expect(vectors.length).toBe(10_000);
    const mismatches: Array<{ i: number; got: unknown; want: unknown }> = [];
    vectors.forEach((v, i) => {
      const got = asJson(
        compute(v.inputs.cfg, v.inputs.params, {
          oracleRaw: BigInt(v.inputs.oracleRaw),
          markRaw: BigInt(v.inputs.markRaw),
          anchorMarkRaw: BigInt(v.inputs.anchorMarkRaw),
          sqrtPriceX96: BigInt(v.inputs.sqrtPriceX96),
          sqrtPriceTopX96: BigInt(v.inputs.sqrtPriceTopX96),
          zeroForOne: v.inputs.zeroForOne,
          readOk: v.inputs.readOk,
        }),
      );
      if (JSON.stringify(got) !== JSON.stringify(v.expected)) mismatches.push({ i, got, want: v.expected });
    });
    expect(mismatches.slice(0, 5)).toEqual([]);
    console.log(`fee vectors: ${vectors.length - mismatches.length}/${vectors.length} match`);
    writeFileSync(`${dir}diff-result-fee.json`, JSON.stringify({ match: vectors.length - mismatches.length, total: vectors.length }));
  });

  it("2,000/2,000 anchor vectors match", () => {
    const vectors = JSON.parse(readFileSync(anchorPath, "utf8")) as AnchorVector[];
    expect(vectors.length).toBe(2_000);
    let ok = 0;
    for (const v of vectors) {
      const r = advanceAnchor(BigInt(v.inputs.anchorMark), BigInt(v.inputs.anchorTime), BigInt(v.inputs.markRaw), BigInt(v.inputs.now), BigInt(v.inputs.tau));
      expect({ mark: r.mark.toString(), time: r.time.toString() }).toEqual(v.expected);
      ok++;
    }
    console.log(`anchor vectors: ${ok}/${vectors.length} match`);
    writeFileSync(`${dir}diff-result-anchor.json`, JSON.stringify({ match: ok, total: vectors.length }));
  });
});
